text:
{
  "tasks": [
    {
      "task_id": "T1",
      "title": "销售数据整体概况统计",
      "business_question": "销售数据的总订单数、总销售额及平均单笔销售额是多少？",
      "priority": "P0",
      "priority_reason": "删除此任务将无法了解数据集的基本规模和价值总量，无法回答探索性分析中的核心特征问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1_1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_orders"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales_amount"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_sales_per_order"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "按地区维度的销售差异分析",
      "business_question": "不同地区的订单数量和销售额分布有何差异？",
      "priority": "P0",
      "priority_reason": "探索“主要差异”需要识别关键维度上的表现对比，地区是销售数据中常见的核心分组维度，缺失将导致无法评估地域性差异。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S2_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_region"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_sum_by_region"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2_2",
          "operation": "sort",
          "params": {
            "field": "sales_sum_by_region",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "按产品类别的销售贡献分析",
      "business_question": "各产品类别的销售额和订单数量分别是多少？",
      "priority": "P0",
      "priority_reason": "产品类别是理解销售结构的主要特征之一，有助于识别高价值品类，符合探索主要特征的需求。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S3_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_sum_by_category"
              },
              {
                "function": "count",
                "field": null,
                "alias": "orders_by_category"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        },
        {
          "step_id": "S3_2",
          "operation": "sort",
          "params": {
            "field": "sales_sum_by_category",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T4",
      "title": "按订单状态的交易质量概览",
      "business_question": "不同订单状态的记录数量分布如何？",
      "priority": "P1",
      "priority_reason": "虽然不直接涉及金额差异，但订单状态反映了交易的有效性或异常比例，属于数据主要特征的补充视角，有助于全面理解数据构成。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S4_1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "order_count_by_status"
              }
            ],
            "dimensions": [
              "field_0004"
            ]
          }
        }
      ]
    }
  ]
}
